static const int PC1[56]={57,49,41,33,25,17,9,1,58,50,42,34,26,18,10,2,59,51,43,35,27,19,11,3,60,52,44,36,63,55,47,39,31,23,15,7,62,54,46,38,30,22,14,6,61,53,45,37,29,21,13,5,28,20,12,4};static const int PC2[48]={14,17,11,24,1,5,3,28,15,6,21,10,23,19,12,4,26,8,16,7,27,20,13,2,41,52,31,37,47,55,30,40,51,45,33,48,44,49,39,56,34,53,46,42,50,36,29,32};int main(void){unsigned long long key;int shifts[16]={1,1,2,2,2,2,2,2,1,2,2,2,2,2,2,1};printf("Enter 64-bit DES key in hex: ");scanf("%llx",&key);int cd=0;for(int i=0;i<56;i++)cd=(cd<<1)|((key>>(64-PC1[i]))&1);int c=(cd>>28)&0xfffffff,d=cd&0xfffffff;for(int r=0;r<16;r++){for(int j=0;j<shifts[r];j++){c=((c<<1)|(c>>27))&0xfffffff;d=((d<<1)|(d>>27))&0xfffffff;}unsigned long long joined=((unsigned long long)c<<28)|d,sub=0;for(int j=0;j<48;j++)sub=(sub<<1)|((joined>>(56-PC2[j]))&1);printf("K%-2d = %012llX (C=%07X D=%07X)\n",r+1,sub,c,d);}puts("The first 24 PC-2 bits select from C; the last 24 select from D.");}
